function solve({config,state,event}) {
  const pos=x=>typeof x==='number'&&Number.isSafeInteger(x)&&x>0;
  const sid=x=>typeof x==='string';
  const sorted=o=>Object.keys(o).sort((a,b)=>a<b?-1:a>b?1:0);
  if(state===null){state={a:config.initial,s:0,g:config.grants||{},r:{},w:{},p:{},d:{}}}
  const e=event||{}, t=e.type, id=e.id, validId=sid(id);
  let status='ignored', amt=e.amount;
  if(t==='receive'){
    if(!validId||!pos(amt)) status='invalid';
    else if(Object.prototype.hasOwnProperty.call(state.r,id)) status='duplicate';
    else if(!Object.prototype.hasOwnProperty.call(state.g,id)||state.g[id]!==amt) status='invalid';
    else {state.r[id]=1;state.a+=amt;status='accepted'}
  } else if(t==='send'||t==='spend'){
    const m=t==='send'?state.w:state.d;
    if(!validId||!pos(amt)) status='invalid';
    else if(Object.prototype.hasOwnProperty.call(m,id)) status=m[id]===amt?'duplicate':'conflict';
    else if(state.a<amt) status='insufficient';
    else {m[id]=amt;state.a-=amt;if(t==='send')state.p[id]=1;else state.s+=amt;status='accepted'}
  } else if(t==='ack'||t==='cancel'){
    if(!validId) status='ignored';
    else if(Object.prototype.hasOwnProperty.call(state.p,id)){
      if(t==='cancel')state.a+=state.w[id];
      delete state.p[id];status='accepted'
    }
  } else status='invalid';
  return {state:state,output:{status:status,available:state.a,spent:state.s,pending:sorted(state.p),received:sorted(state.r)}};
}
